with "F4211_Open_Sales_Orders" as (
select "F4211"."SDKCOO", "F4211"."SDDOCO", "F4211"."SDDCTO", "F4211"."SDSFXO", "F4211"."SDMCU", "F4211"."SDAN8", "F4211"."SDSHAN", case  when "F4211"."SDDRQJ">0 then "PRODDTA".JUL2DATE("F4211"."SDDRQJ") else NULL end  "SDDRQJ", case  when "F4211"."SDPDDJ">0 then "PRODDTA".JUL2DATE("F4211"."SDPDDJ") else NULL end  "SDPDDJ", "F4211"."SDITM", "F4211"."SDLITM", "F4211"."SDLNTY", "F4211"."SDNXTR", "F4211"."SDUOM", "F4211"."SDUORG", "F4211"."SDCARS", "F4211"."SDUOM1", "F4211"."SDPQOR", "F4211"."SDUOM2", "F4211"."SDSQOR", "F4211"."SDUOM4"
 from "PRODDTA"."F4211" "F4211"), "F42140__CSR" as (
select "F42140"."CMAN8", "F0101"."ABALPH"
 from "PRODDTA"."F42140" "F42140", "PRODDTA"."F0101" "F0101"
 where "F42140"."CMRTYPE"='CSR' and "F42140"."CMSLSM"="F0101"."ABAN8") 
select "F4211_Open_Sales_Orders"."SDDOCO" "Order_Number", "F0101_Sold_To_Customer"."ABALPH" "Customer_Name", "F4211_Open_Sales_Orders"."SDNXTR" "Next_Status", "F4211_Open_Sales_Orders"."SDMCU" "Branch_Plant", "F4211_Open_Sales_Orders"."SDDRQJ" "Requested_Date", "F4211_Open_Sales_Orders"."SDPDDJ" "Promised_Ship_Date", sum("F4211_Open_Sales_Orders"."SDUORG"/10000) "Quantity", "F4211_Open_Sales_Orders"."SDUOM" "Unit_Of_Measure", sum(decode("F4211_Open_Sales_Orders"."SDUOM4", "F4211_Open_Sales_Orders"."SDUOM1", "F4211_Open_Sales_Orders"."SDPQOR"/10000, "F4211_Open_Sales_Orders"."SDUOM2", "F4211_Open_Sales_Orders"."SDSQOR"/10000, "F4211_Open_Sales_Orders"."SDUOM", "F4211_Open_Sales_Orders"."SDUORG"/10000, nvl((("F41002_Pricing_UOM_Conversion"."UMCONV"/10000000)*"F4211_Open_Sales_Orders"."SDUORG")/10000, 0))) "Pricing_Quantity", "F4211_Open_Sales_Orders"."SDLITM" "C_2nd_Item_Number", "F4201_Order_Header"."SHHOLD" "Hold_Orders_Code", "F0101_Carrier"."ABALPH" "Carrier_Name", "F4201_Order_Header"."SHMOT" "Mode_of_Transportation", "F4201_Order_Header"."SHDEL1" "Delivery_Instructions_1", "F4201_Order_Header"."SHDEL2" "Delivery_Instructions_2"
 from (((("F4211_Open_Sales_Orders" INNER JOIN "PRODDTA"."F0101" "F0101_Sold_To_Customer" on "F4211_Open_Sales_Orders"."SDAN8"="F0101_Sold_To_Customer"."ABAN8") INNER JOIN "PRODDTA"."F4201" "F4201_Order_Header" on "F4211_Open_Sales_Orders"."SDKCOO"="F4201_Order_Header"."SHKCOO" and "F4211_Open_Sales_Orders"."SDDOCO"="F4201_Order_Header"."SHDOCO" and "F4211_Open_Sales_Orders"."SDDCTO"="F4201_Order_Header"."SHDCTO" and "F4211_Open_Sales_Orders"."SDSFXO"="F4201_Order_Header"."SHSFXO") LEFT OUTER JOIN "PRODDTA"."F41002" "F41002_Pricing_UOM_Conversion" on "F4211_Open_Sales_Orders"."SDMCU"="F41002_Pricing_UOM_Conversion"."UMMCU" and "F4211_Open_Sales_Orders"."SDITM"="F41002_Pricing_UOM_Conversion"."UMITM" and "F4211_Open_Sales_Orders"."SDUOM"="F41002_Pricing_UOM_Conversion"."UMUM" and "F4211_Open_Sales_Orders"."SDUOM4"="F41002_Pricing_UOM_Conversion"."UMRUM") LEFT OUTER JOIN "F42140__CSR" on "F4211_Open_Sales_Orders"."SDSHAN"="F42140__CSR"."CMAN8") LEFT OUTER JOIN "PRODDTA"."F0101" "F0101_Carrier" on "F4211_Open_Sales_Orders"."SDCARS"="F0101_Carrier"."ABAN8"
 where "F4211_Open_Sales_Orders"."SDNXTR"<'570' and "F4211_Open_Sales_Orders"."SDKCOO"='00010' and "F4211_Open_Sales_Orders"."SDLNTY" not  in ('FS', 'T') and "F42140__CSR"."ABALPH"='Garner, Shannon' and "F4211_Open_Sales_Orders"."SDDCTO"<>'SQ'
 group by "F4211_Open_Sales_Orders"."SDPDDJ", "F4211_Open_Sales_Orders"."SDDOCO", "F0101_Sold_To_Customer"."ABALPH", "F4211_Open_Sales_Orders"."SDMCU", "F4211_Open_Sales_Orders"."SDNXTR", "F4211_Open_Sales_Orders"."SDDRQJ", "F0101_Carrier"."ABALPH", "F4211_Open_Sales_Orders"."SDLITM", "F4201_Order_Header"."SHHOLD", "F4201_Order_Header"."SHMOT", "F4201_Order_Header"."SHDEL1", "F4201_Order_Header"."SHDEL2", "F4211_Open_Sales_Orders"."SDUOM"
 order by "Promised_Ship_Date" asc nulls last, "Order_Number" asc nulls last
